-- 1. Kiểm tra 17 Lot B781 HY ngày 19/08/2026
SELECT LotNo, MaterialCode, PackQty, PrintTime, EmpNo, isPrinted
FROM dbo.STB_SavePackingTime_VVT WITH (NOLOCK)
WHERE LotNo IN ('VVQN033R072790', 'VVQO173R072705', 'VVQO173R072737', 'VVQO183R072711', 'VVQO183R072769', 'VVQO193R072702', 'VVQO193R072708', 'VVQO193R072712', 'VVQO193R072735', 'VVQO193R072745', 'VVQO193R072752', 'VVQO193R072760', 'VVQO193R072762', 'VVQO193R072766', 'VVQO203R072711', 'VVQO203R072734', 'VVQO203R072758')
ORDER BY LotNo, PrintTime;

-- 2. Thống kê số Lot theo ngày công đoạn Aging (Route V-26)
SELECT CAST(PRH.JobDate AS DATE) AS Aging_JobDate, COUNT(DISTINCT SI.Barcode) AS Lot_Count
FROM dbo.STB_ProdRouteHist PRH WITH (NOLOCK)
INNER JOIN dbo.STB_SetInfo SI WITH (NOLOCK) ON PRH.ControlNo = SI.ControlNo
WHERE SI.Barcode IN ('VVQN033R072790', 'VVQO113R072735', 'VVQO153R072709', 'VVQO153R072710', 'VVQO153R072711', 'VVQO153R072712', 'VVQO153R072713', 'VVQO153R072714', 'VVQO153R072719', 'VVQO153R072720', 'VVQO153R072721', 'VVQO153R072722', 'VVQO153R072724', 'VVQO153R072726', 'VVQO153R072727', 'VVQO153R072728', 'VVQO163R072709', 'VVQO163R072711', 'VVQO163R072712', 'VVQO163R072742', 'VVQO173R072705', 'VVQO173R072716', 'VVQO173R072718', 'VVQO173R072719', 'VVQO173R072722', 'VVQO173R072731', 'VVQO173R072735', 'VVQO173R072737', 'VVQO173R072751', 'VVQO173R072761', 'VVQO183R072710', 'VVQO183R072711', 'VVQO183R072712', 'VVQO183R072713', 'VVQO183R072714', 'VVQO183R072715', 'VVQO183R072716', 'VVQO183R072717', 'VVQO183R072718', 'VVQO183R072747', 'VVQO183R072760', 'VVQO183R072761', 'VVQO183R072769', 'VVQO183R072770', 'VVQO193R072702', 'VVQO193R072708', 'VVQO193R072710', 'VVQO193R072711', 'VVQO193R072712', 'VVQO193R072713', 'VVQO193R072714', 'VVQO193R072715', 'VVQO193R072716', 'VVQO193R072717', 'VVQO193R072718', 'VVQO193R072725', 'VVQO193R072727', 'VVQO193R072734', 'VVQO193R072735', 'VVQO193R072745', 'VVQO193R072748', 'VVQO193R072749', 'VVQO193R072752', 'VVQO193R072758', 'VVQO193R072760', 'VVQO193R072761', 'VVQO193R072762', 'VVQO193R072766', 'VVQO193R072767', 'VVQO193R072768', 'VVQO193R072777', 'VVQO203R072711', 'VVQO203R072713', 'VVQO203R072725', 'VVQO203R072734', 'VVQO203R072743', 'VVQO203R072758', 'VVQP183R072706', 'VVQP263R072709', 'VVQP263R072710', 'VVQP283R072702')
  AND PRH.RouteCode LIKE 'V-26%'
GROUP BY CAST(PRH.JobDate AS DATE)
ORDER BY Aging_JobDate;

-- 3. Thống kê số Lot theo ngày công đoạn Packing (Route V-28)
SELECT CAST(PRH.JobDate AS DATE) AS Packing_JobDate, COUNT(DISTINCT SI.Barcode) AS Lot_Count
FROM dbo.STB_ProdRouteHist PRH WITH (NOLOCK)
INNER JOIN dbo.STB_SetInfo SI WITH (NOLOCK) ON PRH.ControlNo = SI.ControlNo
WHERE SI.Barcode IN ('VVQN033R072790', 'VVQO113R072735', 'VVQO153R072709', 'VVQO153R072710', 'VVQO153R072711', 'VVQO153R072712', 'VVQO153R072713', 'VVQO153R072714', 'VVQO153R072719', 'VVQO153R072720', 'VVQO153R072721', 'VVQO153R072722', 'VVQO153R072724', 'VVQO153R072726', 'VVQO153R072727', 'VVQO153R072728', 'VVQO163R072709', 'VVQO163R072711', 'VVQO163R072712', 'VVQO163R072742', 'VVQO173R072705', 'VVQO173R072716', 'VVQO173R072718', 'VVQO173R072719', 'VVQO173R072722', 'VVQO173R072731', 'VVQO173R072735', 'VVQO173R072737', 'VVQO173R072751', 'VVQO173R072761', 'VVQO183R072710', 'VVQO183R072711', 'VVQO183R072712', 'VVQO183R072713', 'VVQO183R072714', 'VVQO183R072715', 'VVQO183R072716', 'VVQO183R072717', 'VVQO183R072718', 'VVQO183R072747', 'VVQO183R072760', 'VVQO183R072761', 'VVQO183R072769', 'VVQO183R072770', 'VVQO193R072702', 'VVQO193R072708', 'VVQO193R072710', 'VVQO193R072711', 'VVQO193R072712', 'VVQO193R072713', 'VVQO193R072714', 'VVQO193R072715', 'VVQO193R072716', 'VVQO193R072717', 'VVQO193R072718', 'VVQO193R072725', 'VVQO193R072727', 'VVQO193R072734', 'VVQO193R072735', 'VVQO193R072745', 'VVQO193R072748', 'VVQO193R072749', 'VVQO193R072752', 'VVQO193R072758', 'VVQO193R072760', 'VVQO193R072761', 'VVQO193R072762', 'VVQO193R072766', 'VVQO193R072767', 'VVQO193R072768', 'VVQO193R072777', 'VVQO203R072711', 'VVQO203R072713', 'VVQO203R072725', 'VVQO203R072734', 'VVQO203R072743', 'VVQO203R072758', 'VVQP183R072706', 'VVQP263R072709', 'VVQP263R072710', 'VVQP283R072702')
  AND PRH.RouteCode LIKE 'V-28%'
GROUP BY CAST(PRH.JobDate AS DATE)
ORDER BY Packing_JobDate;
